import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    private static boolean isUppercaseLetter(char c) {
        return c >= 'A' && c <= 'Z';
    }

    private static boolean isDigit(char c) {
        return c >= '0' && c <= '9';
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String plate = reader.readLine();

        if (plate == null) {
            return;
        }

        boolean brazilian = plate.length() == 8
                && isUppercaseLetter(plate.charAt(0))
                && isUppercaseLetter(plate.charAt(1))
                && isUppercaseLetter(plate.charAt(2))
                && plate.charAt(3) == '-'
                && isDigit(plate.charAt(4))
                && isDigit(plate.charAt(5))
                && isDigit(plate.charAt(6))
                && isDigit(plate.charAt(7));

        boolean mercosul = plate.length() == 7
                && isUppercaseLetter(plate.charAt(0))
                && isUppercaseLetter(plate.charAt(1))
                && isUppercaseLetter(plate.charAt(2))
                && isDigit(plate.charAt(3))
                && isUppercaseLetter(plate.charAt(4))
                && isDigit(plate.charAt(5))
                && isDigit(plate.charAt(6));

        System.out.println(brazilian ? 1 : mercosul ? 2 : 0);
    }
}
